def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, (1, dim))
    temp = 1000
    alpha = 0.01
    for _ in range(budget):
        trial = x.copy()
        step_size = max(np.exp(-temp/alpha), 1e-6)
        trial += step_size * np.random.normal(size=(1, dim))
        for i in range(dim - 1):
            trial[0, i+1] = min(max(trial[0, i+1], lb[i]), ub[i])
            trial[0, i] = min(max(trial[0, i], lb[i]), ub[i])
        f_trial = func(trial)
        if f_trial < func(x):
            x = trial
        else:
            delta_f = func(x) - f_trial
            if rng.random() < np.exp(-delta_f/temp):
                x = trial
        temp *= 0.99
    return x[0]

def algorithm(func, dim, lb, ub, budget, rng):
    candidates = np.random.uniform(lb, ub, (budget, dim))
    for i in range(budget - 1):
        new_candidate = np.copy(candidates[i])
        for j in range(dim):
            new_candidate[j] += rng.normal(0, 0.5)
            new_candidate[j] = max(lb, min(new_candidate[j], ub))
        if func(new_candidate) < func(candidates[i + 1]):
            candidates[i + 1] = new_candidate
    return np.min(np.array([candidates[i] for i in range(budget) if func(candidates[i]) == np.inf]), axis=0)

